cat > migrations/002_wallet_adjustments.sql <<'EOF'
-- Audit log of manual store-credit corrections made by admins.
create table wallet_adjustments (
  id serial primary key,
  user_id integer not null references users(id),
  admin_id integer not null references users(id),
  amount_cents integer not null,
  reason text not null,
  created_at timestamptz not null default now()
);

create index wallet_adjustments_user_id_idx on wallet_adjustments (user_id);
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
route='''  app.post("/wallets/:userId/adjustments", async (req, res) => {
    const admin = res.locals.user;
    if (admin.role !== "admin") return sendError(res, 403, "forbidden", "Admins only");

    const userId = Number(req.params.userId);
    if (!Number.isSafeInteger(userId) || userId < 1 || userId > INT4_MAX) {
      return sendError(res, 400, "invalid_request", "userId must be a positive integer");
    }
    const { amountCents, reason } = req.body ?? {};
    if (!Number.isInteger(amountCents) || amountCents === 0 || Math.abs(amountCents) > INT4_MAX) {
      return sendError(res, 400, "invalid_request", "amountCents must be a non-zero integer");
    }
    if (typeof reason !== "string" || reason.trim() === "") {
      return sendError(res, 400, "invalid_request", "reason is required");
    }

    const client = await pool.connect();
    try {
      await client.query("begin");
      // Single guarded UPDATE: row-locks the wallet, so concurrent adjustments can't push it below 0.
      const updated = await client.query(
        "update wallets set balance_cents = balance_cents + $1 where user_id = $2 and balance_cents + $1 >= 0 returning balance_cents",
        [amountCents, userId],
      );
      if (updated.rows.length === 0) {
        await client.query("rollback");
        const exists = await pool.query("select 1 from wallets where user_id = $1", [userId]);
        if (exists.rows.length === 0) return sendError(res, 404, "not_found", "Wallet not found");
        return sendError(res, 409, "insufficient_balance", "Adjustment would make the balance negative");
      }
      const { rows } = await client.query(
        "insert into wallet_adjustments (user_id, admin_id, amount_cents, reason) values ($1, $2, $3, $4) returning id, created_at",
        [userId, admin.id, amountCents, reason],
      );
      await client.query("commit");
      res.status(201).json({
        id: rows[0].id,
        userId,
        adminId: admin.id,
        amountCents,
        reason,
        balanceCents: updated.rows[0].balance_cents,
        createdAt: rows[0].created_at,
      });
    } catch (err) {
      await client.query("rollback").catch(() => {});
      if ((err as { code?: string }).code === "22003") {
        return sendError(res, 400, "invalid_request", "Resulting balance is out of range");
      }
      throw err;
    } finally {
      client.release();
    }
  });

'''
s=s.replace('  app.use((err: Error',route+'  app.use((err: Error',1)
s=s.replace('export function sendError','const INT4_MAX = 2_147_483_647;\n\nexport function sendError',1)
open(p,'w').write(s)

t=open('test/app.test.ts').read()
t+='''
const adjust = (token: string, userId: number, body: unknown) =>
  fetch(`${base}/wallets/${userId}/adjustments`, {
    method: "POST",
    headers: { ...as(token), "content-type": "application/json" },
    body: JSON.stringify(body),
  });
const balance = async (userId: number) =>
  (await pool.query("select balance_cents from wallets where user_id = $1", [userId])).rows[0].balance_cents;

test("wallet adjustments are admin-only", async () => {
  const res = await adjust("alice-token", 1, { amountCents: 100, reason: "self-service" });
  assert.equal(res.status, 403);
  assert.equal(await balance(1), 10000);
});

test("admin adjusts a wallet and the adjustment is recorded", async () => {
  const res = await adjust("admin-token", 2, { amountCents: 250, reason: "goodwill" });
  assert.equal(res.status, 201);
  assert.equal((await res.json()).balanceCents, 750);
  const neg = await adjust("admin-token", 2, { amountCents: -750, reason: "correction" });
  assert.equal(neg.status, 201);
  assert.equal(await balance(2), 0);
  const { rows } = await pool.query("select user_id, admin_id, amount_cents, reason from wallet_adjustments where user_id = 2 order by id");
  assert.deepEqual(rows, [
    { user_id: 2, admin_id: 3, amount_cents: 250, reason: "goodwill" },
    { user_id: 2, admin_id: 3, amount_cents: -750, reason: "correction" },
  ]);
});

test("adjustment that would take the balance below 0 is rejected and not recorded", async () => {
  const before = (await pool.query("select count(*)::int as n from wallet_adjustments")).rows[0].n;
  const res = await adjust("admin-token", 3, { amountCents: -1, reason: "oops" });
  assert.equal(res.status, 409);
  assert.equal(await balance(3), 0);
  assert.equal((await pool.query("select count(*)::int as n from wallet_adjustments")).rows[0].n, before);
});

test("adjustment validates input and wallet existence", async () => {
  assert.equal((await adjust("admin-token", 1, { amountCents: 1.5, reason: "x" })).status, 400);
  assert.equal((await adjust("admin-token", 1, { amountCents: "5", reason: "x" })).status, 400);
  assert.equal((await adjust("admin-token", 1, { amountCents: 5 })).status, 400);
  assert.equal((await adjust("admin-token", 1, { amountCents: 5, reason: "  " })).status, 400);
  assert.equal((await adjust("admin-token", 999, { amountCents: 5, reason: "x" })).status, 404);
  assert.equal((await adjust("admin-token", "abc" as unknown as number, { amountCents: 5, reason: "x" })).status, 400);
});
'''
open('test/app.test.ts','w').write(t)
EOF
